mapper.select:

where 1=1

    and d.input_category = #{query.inputCategory}


    and d.input_type = #{query.inputType}


    and d.status = #{query.status}


    and d.source_name like concat('%', #{query.sourceName}, '%')


    and d.source_code = #{query.sourceCode}


    and d.target_name like concat('%', #{query.targetName}, '%')


    and d.target_code = #{query.targetCode}


    and d.summary_id = #{query.summaryId}


    and (d.input_category like concat('%', #{query.keyword}, '%')
         or d.input_type like concat('%', #{query.keyword}, '%')
         or d.source_name like concat('%', #{query.keyword}, '%')
         or d.target_name like concat('%', #{query.keyword}, '%'))


    and d.created_time >= #{query.startTime}


    and d.created_time <= #{query.endTime}

order by d.created_time desc

select count(1)
from demand_input_summary_item
where input_category = #{inputCategory}
  and input_type = #{inputType}

    and id != #{excludeId}
